 root.querySelector('#kyc-create-supplier')?.addEventListener('click',()=>run(async()=>{const c=await store.detail(current.id),scope=['glf','government'].find(s=>can(account,'create',s));if(!scope||!options.createSupplier)throw Error('FORBIDDEN');await options.createSupplier({id:c.id,name:c.name,draft:supplierDraftFromKyc(c,scope)});}));
 root.querySelector('#kyc-link-supplier')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target);run(async()=>{await associateSupplier(current.id,f.get('supplier'));suppliers=(await directory.load()).suppliers;await open(current.id);});});
 root.querySelector('#kyc-delegation')?.addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target),days=Number(f.get('days'));run(async()=>{await store.delegate(f.get('target'),days?new Date(Date.now()+days*86400000).toISOString():null,f.get('reason'));users=await store.users();notice=tr('Delegación actualizada.','Delegation updated.');});});
  root.querySelectorAll('[data-kyc]').forEach(b=>b.onclick=()=>action(b.dataset.kyc));root.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>run(()=>open(b.dataset.case)));
