  root.querySelector('#kyc-case-search')?.addEventListener('input',ev=>{caseDraft=ev.target.value;});
  root.querySelector('#kyc-case-search-form')?.addEventListener('submit',ev=>{ev.preventDefault();run(async()=>{caseQuery=caseDraft.trim();caseOffset=0;cases=[];caseTotal=0;await load();});});
  root.querySelector('#kyc-supplier-search')?.addEventListener('input',ev=>{const q=ev.target.value.trim().toLocaleLowerCase();root.querySelector('#kyc-supplier-results').innerHTML=q?suppliers.filter(s=>s.active&&(s.legal_name+' '+s.id_number+' '+s.tax_number).toLocaleLowerCase().includes(q)).slice(0,10).map(s=>`<button type="button" class="secondary" data-supplier="${s.id}">${esc(s.legal_name)} · ${esc(s.id_number)}</button>`).join('')||`<p>${tr('No encontrado: complete nombre y correo debajo.','Not found: enter name and email below.')}</p>`:'';root.querySelectorAll('[data-supplier]').forEach(b=>b.onclick=()=>{const s=suppliers.find(s=>s.id===b.dataset.supplier),form=root.querySelector('#kyc-create');form.elements.supplier.value=s.id;form.elements.name.value=s.legal_name;form.elements.email.value=s.email;form.elements.relation.value='supplier';root.querySelector('#kyc-source').textContent=tr('Proveedor vinculado: ','Linked supplier: ')+s.legal_name;});});
  root.querySelector('#kyc-create')?.addEventListener('submit',ev=>{ev.preventDefault();const form=ev.target,values=new FormData(form);run(async()=>{const relation=values.get('relation'),id=await store.create(['staff','board'].includes(relation)?null:values.get('supplier'),values.get('name'),values.get('email'),relation);await load();await open(id);});});
  root.querySelector('#kyc-review')?.addEventListener('submit',ev=>{ev.preventDefault();const values=new FormData(ev.target);run(async()=>{if(['approved','not_approved'].includes(values.get('state')))await store.finish(current,values.get('state'),values.get('note'),values.get('confirm')==='on',{risk:values.get('risk'),report:values.get('report'),issued:values.get('issued'),due:values.get('schedule_mode')==='manual'?values.get('due'):null,reason:values.get('reason')||'',exception:values.get('exception')==='on'});else await store.review(current.id,values.get('state'),values.get('note'),values.get('confirm')==='on');await open(current.id);notice=tr('Revisión guardada.','Review saved.');});});
  root.querySelectorAll('[data-file-download]').forEach(b=>b.onclick=()=>run(async()=>{const f=current.files.find(f=>f.id===b.dataset.fileDownload);const {downloadBlob}=await import('./kyc-pdf.js');downloadBlob(await store.download(f),f.name);}));
  root.querySelectorAll('[data-internal-file],[data-upload]').forEach(el=>el.onchange=()=>{const file=el.files[0],slot=el.dataset.upload||el.dataset.internalFile;if(!file)return;run(async()=>{if(store.token||screen==='assisted')await flush();if(!await validFile(file,['signed','report','countersigned'].includes(slot))){fileErrors['file:'+slot]=tr('Archivo no válido: use '+(['signed','report','countersigned'].includes(slot)?'PDF':'PDF, JPG o PNG')+' de hasta 10 MB.','Invalid file: use '+(['signed','report','countersigned'].includes(slot)?'PDF':'PDF, JPG or PNG')+' up to 10 MB.');focusError=true;return;}await store.upload(current,slot,file);delete fileErrors['file:'+slot];signatureChecked=false;current=store.token?await store.read():await store.detail(current.id);notice=tr('Documento incorporado.','Document attached.');});});
  root.querySelector('#kyc-form')?.addEventListener('submit',ev=>ev.preventDefault());
