  root.querySelector('#kyc-phone-number')?.addEventListener('input',phoneChanged);
  root.querySelector('#kyc-phone-number')?.addEventListener('change',()=>{const value=root.querySelector('#kyc-phone-number').value;if(/^(\+|00)/.test(value.trim())){const parsed=splitPhone(value,phoneCountry);phoneCountry=parsed.country;root.querySelector('#kyc-phone-country').innerHTML=phoneOptions(parsed.country,'',lang).html;root.querySelector('#kyc-phone-number').value=parsed.number;root.querySelector('#kyc-phone-country').dispatchEvent(new Event('kyc:sync'));}phoneChanged();});
  root.querySelector('#kyc-city-select')?.addEventListener('change',ev=>{readFields();cityOther=ev.target.value==='__other';current.answers.city=cityOther?'':ev.target.value;dirty();refreshValidation();draw();if(cityOther)root.querySelector('#kyc-city-other')?.focus();});
